From fc37d0570ce50c8b553a093da8ef53c010f35c73 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:32:26 +0100
Subject: [PATCH] applets/appmenu: fix keyboard shortcuts and their underlines

Parenting the menu made QMenu replace the panel as its transient parent,
so Alt+letter only opened it once, and Kirigami gave letters still held
by deleted buttons; now we keep the panel and underline the app's own.

BUG: 512473
---
 applets/appmenu/appmenuapplet.cpp    |  8 +++++++-
 applets/appmenu/qml/MenuDelegate.qml | 19 ++++++++++++++++---
 applets/appmenu/qml/main.qml         |  3 +--
 3 files changed, 24 insertions(+), 6 deletions(-)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..d468c46d2f 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -191,7 +191,13 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)

         if (view() == FullView) {
             if (!m_currentMenu) {
-                m_currentMenu = new QMenu(qobject_cast<QWidget *>(actionMenu->parent()));
+                // No parent widget: QMenu would make its window the transient parent on show, instead of the panel
+                m_currentMenu = new QMenu;
+                if (QObject *menuOwner = actionMenu->parent()) {
+                    connect(menuOwner, &QObject::destroyed, m_currentMenu, [menu = m_currentMenu.data()] {
+                        delete menu;
+                    });
+                }
                 connect(m_currentMenu, &QMenu::aboutToHide, this, &AppMenuApplet::onMenuAboutToHide, Qt::UniqueConnection);
             } else if (m_sourceMenu != actionMenu) {
                 auto menuAction = m_currentMenu->menuAction();
diff --git a/applets/appmenu/qml/MenuDelegate.qml b/applets/appmenu/qml/MenuDelegate.qml
index 9bcbaf6052..55b1f94554 100644
--- a/applets/appmenu/qml/MenuDelegate.qml
+++ b/applets/appmenu/qml/MenuDelegate.qml
@@ -51,8 +51,9 @@ AbstractButton {
         return MenuDelegate.State.Rest;
     }

-    Kirigami.MnemonicData.controlType: Kirigami.MnemonicData.SecondaryControl
-    Kirigami.MnemonicData.label: text
+    // The app handles Alt+letter itself, so underline its own accelerator
+    // rather than letting Kirigami pick one shared with the rest of the shell
+    property bool showMnemonic: false

     topPadding: rest.margins.top
     leftPadding: rest.margins.left
@@ -72,7 +73,19 @@ AbstractButton {
     }

     contentItem: PC3.Label {
-        text: controlRoot.Kirigami.MnemonicData.richTextLabel
+        text: {
+            let underlined = !controlRoot.showMnemonic;
+            return controlRoot.text.replace(/&(.)/g, (match, character) => {
+                if (character === "&") {
+                    return "&amp;";
+                }
+                if (underlined) {
+                    return character;
+                }
+                underlined = true;
+                return `<u>${character}</u>`;
+            });
+        }
         textFormat: Text.StyledText
         verticalAlignment: Text.AlignVCenter
         elide: Text.ElideRight
diff --git a/applets/appmenu/qml/main.qml b/applets/appmenu/qml/main.qml
index e9f5280a3f..81ac6f3eba 100644
--- a/applets/appmenu/qml/main.qml
+++ b/applets/appmenu/qml/main.qml
@@ -16,7 +16,6 @@ import org.kde.plasma.plasmoid
 import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.private.keyboardindicator as KeyboardIndicator
 import org.kde.plasma.components as PlasmaComponents3
-import org.kde.kirigami as Kirigami
 import plasma.applet.org.kde.plasma.appmenu

 PlasmoidItem {
@@ -120,7 +119,7 @@ PlasmoidItem {
                 Layout.fillWidth: root.vertical
                 Layout.fillHeight: !root.vertical
                 text: activeMenu
-                Kirigami.MnemonicData.active: altState.pressed
+                showMnemonic: altState.pressed

                 down: Plasmoid.currentIndex === index
                 visible: text !== "" && (activeActions?.visible ?? false)
